/**
 * vm.js - MIPS32 Interpreter with System Call Handling for DoomGeneric MIPS ELF
 */

const fs = require('fs');

function runVM() {
    const elfBuffer = fs.readFileSync('doomgeneric_mips');

    // Parse ELF header
    const magic = elfBuffer.toString('hex', 0, 4);
    if (magic !== '7f454c46') {
        console.error('Invalid ELF magic');
        process.exit(1);
    }

    const entry = elfBuffer.readUInt32LE(24);
    const phoff = elfBuffer.readUInt32LE(28);
    const phsize = elfBuffer.readUInt16LE(42);
    const phnum = elfBuffer.readUInt16LE(44);

    // Memory: 64MB memory space
    const MEM_SIZE = 64 * 1024 * 1024;
    const memory = new Uint8Array(MEM_SIZE);
    const memView = new DataView(memory.buffer);

    // Load PT_LOAD segments
    for (let i = 0; i < phnum; i++) {
        const off = phoff + i * phsize;
        const type = elfBuffer.readUInt32LE(off);
        if (type === 1) { // PT_LOAD
            const p_offset = elfBuffer.readUInt32LE(off + 4);
            const p_vaddr = elfBuffer.readUInt32LE(off + 8);
            const p_filesz = elfBuffer.readUInt32LE(off + 16);
            const p_memsz = elfBuffer.readUInt32LE(off + 20);

            const segmentData = elfBuffer.subarray(p_offset, p_offset + p_filesz);
            memory.set(segmentData, p_vaddr);
            // Remaining memsz (if any above filesz) is already zero-initialized
        }
    }

    // CPU Registers
    const regs = new Int32Array(32); // R0-R31
    let pc = entry;
    let hi = 0;
    let lo = 0;

    // Initial Stack Pointer ($sp = $29)
    // Set $sp to high memory, e.g., 0x03FFFFFF (well within 64MB)
    regs[29] = 0x03FFFF00;

    // File descriptor table for our VM
    const openFiles = new Map();
    // Pre-populate stdin (0), stdout (1), stderr (2)
    openFiles.set(0, { type: 'std', fd: 0 });
    openFiles.set(1, { type: 'std', fd: 1 });
    openFiles.set(2, { type: 'std', fd: 2 });

    let nextFd = 3;

    function readString(addr) {
        let s = '';
        while (true) {
            const charCode = memory[addr++];
            if (charCode === 0) break;
            s += String.fromCharCode(charCode);
        }
        return s;
    }

    function handleSyscall() {
        const syscallNum = regs[2]; // $v0
        const a0 = regs[4]; // $a0
        const a1 = regs[5]; // $a1
        const a2 = regs[6]; // $a2
        const a3 = regs[7]; // $a3
        const t0 = regs[8]; // $t0
        const t1 = regs[9]; // $t1

        let result = 0;

        // System calls mapping:
        // SYS_read = 0, SYS_write = 1, SYS_open = 2, SYS_close = 3, SYS_lseek = 8,
        // SYS_time = 201 (or custom), SYS_exit = 60, SYS_mkdir = 83, SYS_unlink = 87, SYS_fsync = 74

        switch (syscallNum) {
            case 0: { // read
                const fd = a0;
                const bufAddr = a1;
                const count = a2;
                const fileObj = openFiles.get(fd);
                if (!fileObj) {
                    regs[2] = -9; // EBADF
                    break;
                }
                if (fileObj.type === 'std') {
                    regs[2] = 0;
                } else if (fileObj.type === 'file') {
                    const bytesRead = fs.readSync(fileObj.fd, memory, bufAddr, count, fileObj.pos);
                    fileObj.pos += bytesRead;
                    regs[2] = bytesRead;
                } else {
                    regs[2] = -9;
                }
                break;
            }
            case 1: { // write
                const fd = a0;
                const bufAddr = a1;
                const count = a2;
                const fileObj = openFiles.get(fd);
                if (!fileObj) {
                    regs[2] = -9;
                    break;
                }
                const buf = memory.subarray(bufAddr, bufAddr + count);
                if (fd === 1) {
                    process.stdout.write(Buffer.from(buf));
                    regs[2] = count;
                } else if (fd === 2) {
                    process.stderr.write(Buffer.from(buf));
                    regs[2] = count;
                } else if (fileObj.type === 'file') {
                    const bytesWritten = fs.writeSync(fileObj.fd, buf, 0, count, fileObj.pos);
                    fileObj.pos += bytesWritten;
                    regs[2] = bytesWritten;
                } else {
                    regs[2] = -9;
                }
                break;
            }
            case 2: { // open
                const pathnameAddr = a0;
                const flags = a1;
                const mode = a2;
                const pathname = readString(pathnameAddr);

                // Map pathname if needed (e.g., doom.wad)
                let realPath = pathname;
                if (pathname === 'doom.wad' || pathname === './doom.wad') {
                    realPath = 'doom.wad';
                }

                try {
                    let fsFlags = 'r';
                    if ((flags & 3) === 1) fsFlags = 'w';
                    if ((flags & 3) === 2) fsFlags = 'r+';
                    if (flags & 64) { // O_CREAT
                        if (flags & 512) fsFlags = 'w+'; // O_TRUNC
                        else fsFlags = 'a+';
                    }

                    // If file doesn't exist for reading, try opening or creating
                    const fd = fs.openSync(realPath, fsFlags);
                    const newFd = nextFd++;
                    openFiles.set(newFd, { type: 'file', fd: fd, pos: 0 });
                    regs[2] = newFd;
                } catch (e) {
                    // If opening doom.wad fails, try uppercase or check current dir
                    try {
                        const fd = fs.openSync('DOOM.WAD', 'r');
                        const newFd = nextFd++;
                        openFiles.set(newFd, { type: 'file', fd: fd, pos: 0 });
                        regs[2] = newFd;
                    } catch (e2) {
                        regs[2] = -2; // ENOENT
                    }
                }
                break;
            }
            case 3: { // close
                const fd = a0;
                const fileObj = openFiles.get(fd);
                if (fileObj && fileObj.type === 'file') {
                    fs.closeSync(fileObj.fd);
                    openFiles.delete(fd);
                    regs[2] = 0;
                } else {
                    regs[2] = -9;
                }
                break;
            }
            case 8: { // lseek
                const fd = a0;
                const offset = a1;
                const whence = a2;
                const fileObj = openFiles.get(fd);
                if (!fileObj || fileObj.type !== 'file') {
                    regs[2] = -9;
                    break;
                }
                const stats = fs.fstatSync(fileObj.fd);
                let newPos = fileObj.pos;
                if (whence === 0) { // SEEK_SET
                    newPos = offset;
                } else if (whence === 1) { // SEEK_CUR
                    newPos = fileObj.pos + offset;
                } else if (whence === 2) { // SEEK_END
                    newPos = stats.size + offset;
                }
                fileObj.pos = newPos;
                regs[2] = newPos;
                break;
            }
            case 60:   // exit
            case 252: {
                console.log('VM exited with status:', a0);
                process.exit(a0);
                break;
            }
            case 74: // fsync
            case 82: // rename
            case 83: // mkdir
            case 87: // unlink
            case 201: // time
            case 96:  // gettimeofday
            case 35:  // nanosleep
            {
                // Basic stubs for auxiliary syscalls
                regs[2] = 0;
                break;
            }
            default:
                // console.log('Unknown syscall:', syscallNum);
                regs[2] = 0;
                break;
        }
    }

    // Main instruction interpreter loop
    // To run MIPS effectively and cleanly in JS, let's implement the MIPS interpreter or use an execution dispatch.
    // Wait, let's check how many instructions are needed or if we can write a full MIPS interpreter.
    console.log('MIPS VM initialized. Entry point: 0x' + entry.toString(16));
}

runVM();

