/**
 * vm.js - MIPS32 Interpreter with System Call Handling and Frame Saving for DoomGeneric MIPS ELF
 */

const fs = require('fs');

function runVM() {
    const elfBuffer = fs.readFileSync('doomgeneric_mips');

    // Parse ELF header
    const magic = elfBuffer.toString('hex', 0, 4);
    if (magic !== '7f454c46') {
        console.error('Invalid ELF magic');
        process.exit(1);
    }

    const entry = elfBuffer.readUInt32LE(24);
    const phoff = elfBuffer.readUInt32LE(28);
    const phsize = elfBuffer.readUInt16LE(42);
    const phnum = elfBuffer.readUInt16LE(44);

    // Memory: 64MB memory space
    const MEM_SIZE = 64 * 1024 * 1024;
    const memory = new Uint8Array(MEM_SIZE);
    const memView = new DataView(memory.buffer);

    // Load PT_LOAD segments
    for (let i = 0; i < phnum; i++) {
        const off = phoff + i * phsize;
        const type = elfBuffer.readUInt32LE(off);
        if (type === 1) { // PT_LOAD
            const p_offset = elfBuffer.readUInt32LE(off + 4);
            const p_vaddr = elfBuffer.readUInt32LE(off + 8);
            const p_filesz = elfBuffer.readUInt32LE(off + 16);
            const p_memsz = elfBuffer.readUInt32LE(off + 20);

            const segmentData = elfBuffer.subarray(p_offset, p_offset + p_filesz);
            memory.set(segmentData, p_vaddr);
        }
    }

    // CPU Registers
    const regs = new Int32Array(32); // R0-R31
    let pc = entry;
    let hi = 0;
    let lo = 0;

    // Initial Stack Pointer ($sp = $29)
    regs[29] = 0x03FFFF00;

    // File descriptor table for VM
    const openFiles = new Map();
    openFiles.set(0, { type: 'std', fd: 0 });
    openFiles.set(1, { type: 'std', fd: 1 });
    openFiles.set(2, { type: 'std', fd: 2 });
    let nextFd = 3;

    function readString(addr) {
        let s = '';
        while (true) {
            const charCode = memory[addr++];
            if (charCode === 0) break;
            s += String.fromCharCode(charCode);
        }
        return s;
    }

    function handleSyscall() {
        const syscallNum = regs[2]; // $v0
        const a0 = regs[4]; // $a0
        const a1 = regs[5]; // $a1
        const a2 = regs[6]; // $a2
        const a3 = regs[7]; // $a3

        switch (syscallNum) {
            case 0: { // read
                const fd = a0;
                const bufAddr = a1;
                const count = a2;
                const fileObj = openFiles.get(fd);
                if (!fileObj) {
                    regs[2] = -9;
                    break;
                }
