                    regs[2] = 0;
                } else if (fileObj.type === 'file') {
                    const bytesRead = fs.readSync(fileObj.fd, memory, bufAddr, count, fileObj.pos);
                    fileObj.pos += bytesRead;
                    regs[2] = bytesRead;
                } else {
                    regs[2] = -9;
                }
                break;
            }
            case 1: { // write
                const fd = a0;
                const bufAddr = a1;
                const count = a2;
                const fileObj = openFiles.get(fd);
                if (!fileObj) {
                    regs[2] = -9;
                    break;
                }
                const buf = memory.subarray(bufAddr, bufAddr + count);
                if (fd === 1) {
                    process.stdout.write(Buffer.from(buf));
                    regs[2] = count;
                } else if (fd === 2) {
                    process.stderr.write(Buffer.from(buf));
                    regs[2] = count;
                } else if (fileObj.type === 'file') {
                    const bytesWritten = fs.writeSync(fileObj.fd, buf, 0, count, fileObj.pos);
                    fileObj.pos += bytesWritten;
                    regs[2] = bytesWritten;
                } else {
                    regs[2] = -9;
                }
                break;
            }
            case 2: { // open
                const pathnameAddr = a0;
