                        const newFd = nextFd++;
                        openFiles.set(newFd, { type: 'file', fd: fd, pos: 0 });
                        regs[2] = newFd;
                    } catch (e2) {
                        regs[2] = -2;
                    }
                }
                break;
            }
            case 3: { // close
                const fd = a0;
                const fileObj = openFiles.get(fd);
                if (fileObj && fileObj.type === 'file') {
                    fs.closeSync(fileObj.fd);
                    openFiles.delete(fd);
                    regs[2] = 0;
                } else {
                    regs[2] = -9;
                }
                break;
            }
            case 8: { // lseek
                const fd = a0;
                const offset = a1;
                const whence = a2;
                const fileObj = openFiles.get(fd);
                if (!fileObj || fileObj.type !== 'file') {
                    regs[2] = -9;
                    break;
                }
                const stats = fs.fstatSync(fileObj.fd);
                let newPos = fileObj.pos;
                if (whence === 0) newPos = offset;
                else if (whence === 1) newPos = fileObj.pos + offset;
                else if (whence === 2) newPos = stats.size + offset;
                fileObj.pos = newPos;
                regs[2] = newPos;
                break;
            }
            case 60:
            case 252: {
                console.log('VM exited.');
                process.exit(a0);
                break;
            }
            default:
                regs[2] = 0;
                break;
        }
    }

    console.log('VM ready to run.');
}

